          "quote": "(comp (ref \"R15\") (value \"0\")"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"/NET0006\") ... (node (ref \"J4\") (pin \"20\")) (node (ref \"R7\") (pin \"2\"))"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"/NET0042\") ... (node (ref \"J4\") (pin \"22\")) (node (ref \"R8\") (pin \"2\"))"
        },
        {
          "source": "spec",
          "quote": "R9–R12 | 0 Ω (jumpers) | Select which M5Stack bus pin ... supplies PWM1/PWM2"
        },
        {
          "source": "spec",
          "quote": "Short R10, R10 for Core2 and CoreS3 / Short R9, R11 for others"
        }
      ],
      "impact": "The alternate bus GPIO pins are tied together in pairs, potentially shorting distinct M5Stack signals and preventing the intended variant-specific PWM mapping.",
      "confidence": 0.9
    }
